class Solution {
public:
    bool isPossibleToCutPath(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::function<bool(int, int)> dfs = [&](int r, int c) -> bool {
            if (r == m - 1 && c == n - 1) return true;
            grid[r][c] = 0;
            if (r + 1 < m && grid[r + 1][c] == 1 && dfs(r + 1, c)) return true;
            if (c + 1 < n && grid[r][c + 1] == 1 && dfs(r, c + 1)) return true;
            return false;
        };
        if (!dfs(0, 0)) return true;
        grid[0][0] = 1;
        return !dfs(0, 0);
    }
};

class Solution {
    public boolean isPossibleToCutPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        if (!dfs(0, 0, grid, m, n)) return true;
        grid[0][0] = 1;
        return !dfs(0, 0, grid, m, n);
    }
    private boolean dfs(int r, int c, int[][] grid, int m, int n) {
        if (r == m - 1 && c == n - 1) return true;
        grid[r][c] = 0;
        if (r + 1 < m && grid[r + 1][c] == 1 && dfs(r + 1, c, grid, m, n)) return true;
        if (c + 1 < n && grid[r][c + 1] == 1 && dfs(r, c + 1, grid, m, n)) return true;
        return false;
    }
}

